// ---------------------------------------------------------------------------
// Transport guard
// ---------------------------------------------------------------------------

function assertSecureTransport(
  url: string,
  opts: { allowInsecureHttp: boolean; auth: boolean; credentials: string },
): void {
  const { allowInsecureHttp, auth, credentials } = opts;
  // Credentials are only allowed over https. Loopback hosts may use http;
  // other hosts require the allowInsecureHttp development option.
  // Unparseable URLs and non-http(s) protocols are rejected.
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    throw new Error(
      `Client produced an unparseable URL (${JSON.stringify(url)}); refusing to send credentials.`,
    );
  }
  if (parsed.protocol === "https:" || parsed.protocol === "wss:") return;
  const h = parsed.hostname;
  const isLoopback =
    h === "localhost" ||
    h.endsWith(".localhost") ||
    h === "127.0.0.1" ||
    h === "::1" ||
    h === "[::1]";
  const isInsecureScheme = parsed.protocol === "http:" || parsed.protocol === "ws:";
  const insecureAllowed = isInsecureScheme && (isLoopback || allowInsecureHttp);
  if (!insecureAllowed) {
    throw new Error(
      parsed.protocol === "http:"
        ? `Refusing to send credentials over http:// to non-loopback host "${h}". Use https:// in production; set allowInsecureHttp on the client options for LAN/device development.`
        : `Unsupported protocol ${parsed.protocol} for credential-bearing requests.`,
    );
  }
  // allowInsecureHttp permits the HTTP connection itself, but never for
  // credential-bearing requests (auth or cookies) to non-loopback hosts.
  // Cookies also count: even with auth:false, `credentials: "include"` (or
  // `"same-origin"` to a same-origin http target) still sends cookies.
  if (isInsecureScheme && !isLoopback && (auth || credentials !== "omit")) {
    throw new Error(
      `Refusing to send credentials over http:// to non-loopback host "${h}". Set allowInsecureHttp for the connection, but credentialed requests (auth: true or credentials !== "omit") still require https:// or a loopback host.`,
    );
  }
}

// ---------------------------------------------------------------------------
// Application-facing primitives
// ---------------------------------------------------------------------------

/** Expiry (epoch ms) from an unverified JWT `exp` claim, for scheduling
    only; verification is server-side. Returns null where `atob` is missing
    (some JS runtimes). This reads the claim and does not renew anything. */
export function jwtExpiry(token: string): number | null {
  try {
    if (typeof atob !== "function") return null;
    const part = token.split(".")[1];
    if (!part) return null;
    const b64 = part.replace(/-/g, "+").replace(/_/g, "/");
    const json = decodeURIComponent(
      atob(b64)
        .split("")
        .map((c) => "%" + ("00" + c.charCodeAt(0).toString(16)).slice(-2))
        .join(""),
    );
    const exp = JSON.parse(json)?.exp;
    return typeof exp === "number" ? exp * 1000 : null;
  } catch {
    return null;
  }
}

/** Coalesce concurrent invocations of `fn` into one in-flight promise:
 *  joiners share the initiator's result, and the next call after it settles
 *  starts a fresh one. Without this, parallel 401s can each renew the
 *  credential, and rotating refresh tokens invalidate the earlier results.
 *
 *  Single-flight is scoped to one closure, so use one per credential source.
 *  Cross-tab coordination is left to the application. */
export function singleFlight<T>(fn: () => Promise<T>): () => Promise<T> {
  let inFlight: Promise<T> | null = null;
  return () => {
    if (inFlight === null) {
      inFlight = fn().finally(() => {
        inFlight = null;
      });
    }
    return inFlight;
  };
}

// ---------------------------------------------------------------------------
// Transport
// ---------------------------------------------------------------------------

export type TransportScheme = "bearer" | "cookie" | "none";

/** Render a key for an error message, escaping quotes and control
 *  characters. */
function escapeKeyForMessage(key: string): string {
  return key.replace(/[\\\"\x00-\x1f\x7f]/g, "�");
}

/** WebSocket ticket configuration. It applies with or without a declared
 *  flow; config-only clients get a synthetic operation. */
export interface TransportPolicy {
  readonly scheme: TransportScheme;
  /** OPERATIONS key of the WS ticket mint, when one is wired. */
  readonly wsTicket?: string | null;
}

/** Replay bound for the 401 path. A request that failed authentication can
 *  be re-sent, but not looped: three sends is the maximum per call. This is
 *  fixed by the transport, not configurable by the application. */
const MAX_REPLAYS = 2;

export function createTransport(
  options: TransportOptions,
  policy: TransportPolicy,
  operations: Record<string, Readonly<OperationSpec>>,
): Transport {
  const { baseUrl, credentials } = options;
  const scheme = policy.scheme;
  // Bind fetch to its original receiver: calling an unbound
  // globalThis.fetch reference throws "Illegal invocation" in several
  // browser engines.
  const boundFetch =
    options.fetch !== undefined ? options.fetch : globalThis.fetch.bind(globalThis);

  // Dispatch observers without delaying the request. The `void` callback
  // types accept async functions, whose rejections a surrounding try/catch
  // cannot see, so handle both synchronous and asynchronous errors.
  function notifyObserver(fn: () => unknown): void {
    try {
      const result = fn();
      if (result instanceof Promise) result.catch(() => {});
    } catch {}
  }

  // Release a discarded response's connection for reuse. Node's fetch
  // (undici) only returns pooled sockets once the body is consumed or
  // cancelled; a replayed 401 or an unread `void` body would otherwise pin
  // its connection until garbage collection.
  async function releaseBody(response: Response): Promise<void> {
    try {
      await response.body?.cancel();
    } catch {}
  }

  // Drain a response whose body was cloned for an observer. Cancelling one
  // branch of a teed body only settles once the sibling branch is consumed
  // or cancelled, so awaiting cancel() would hang a successful `void` call
  // whose observer never reads its copy. Reading the original to the end
  // settles the tee and returns the connection to the pool either way.
  async function drainBody(response: Response): Promise<void> {
    try {
      await response.arrayBuffer();
    } catch {}
  }

  function interpolate(op: Readonly<OperationSpec>, args: CallArgs | undefined): string {
    if (!op.path.includes("{")) return op.path;
    const values = args?.params ?? {};
    return op.path.replace(/\{([^}]+)\}/g, (_hole, name: string) => {
      const v = values[name];
      if (v === undefined) {
        throw new Error(
          `Missing path parameter "${name}" for ${op.method} ${op.path} — the typed client always supplies it.`,
        );
      }
      return encodeURIComponent(String(v));
    });
  }

  /** Arrays expand to repeated keys (?tag=a&tag=b), the conventional
   *  encoding for list-valued parameters in HTTP calls, URL builders, and
   *  WebSocket upgrades. */
  function appendQuery(params: URLSearchParams, query: Record<string, unknown>): void {
    for (const [key, value] of Object.entries(query)) {
      for (const v of Array.isArray(value) ? value : [value]) {
        if (v !== undefined && v !== null) {
          params.append(key, String(v));
        }
      }
    }
  }

  function buildUrl(op: Readonly<OperationSpec>, args: CallArgs | undefined): string {
    let url = `${baseUrl}${interpolate(op, args)}`;
    if (args?.query) {
      const params = new URLSearchParams();
      appendQuery(params, args.query);
      const qs = params.toString();
      if (qs) url += `?${qs}`;
    }
    return url;
  }

  interface InternalCall {
    /** Replays already consumed on this call. */
    replays?: number;
    /** Bearer used for the replay: the renewal hook's return value, not a
     *  re-read of the application's credential source. */
    tokenOverride?: string;
  }

  /** Resolve an OPERATIONS key. Every key comes from generated code, so a
   *  missing entry means the client and its OPERATIONS table disagree;
   *  throw instead of dereferencing undefined later. */
  function requireOp(key: string): Readonly<OperationSpec> {
    const op = operations[key];
    if (op === undefined) {
      throw new Error(
        `Unknown operation "${escapeKeyForMessage(key)}" — this client's OPERATIONS table has no such key.`,
      );
    }
    return op;
  }

  async function executeInternal<T = unknown>(
    opKey: string | Readonly<OperationSpec>,
    args?: CallArgs,
    internal?: InternalCall,
  ): Promise<T> {
    const op = typeof opKey === "string" ? requireOp(opKey) : opKey;
    const authMode = op.auth;
    const permissive = authMode === "optional";
    const method = op.method;

    const url = buildUrl(op, args);

    const headers: Record<string, string> = {
      ...(args?.body !== undefined ? { "Content-Type": "application/json" } : {}),
      ...(options.requestInit?.headers ?? {}),
    };

    // Credentials are only sent over https, to loopback hosts over http,
    // or when the client was explicitly configured with allowInsecureHttp.
    // allowInsecureHttp permits the HTTP connection itself, but never for
    // credential-bearing requests (auth or cookies) to non-loopback hosts.
    assertSecureTransport(url, {
      allowInsecureHttp: options.allowInsecureHttp === true,
      auth: authMode !== "none",
      credentials,
    });

    // Observer errors do not affect the request.
    notifyObserver(() => options.onRequest?.(op, url));

    // Bearer sent with this call, so the replay path does not re-send the
    // credential the server rejected.
    let sentBearer: string | null = null;
    if (scheme === "bearer" && authMode !== "none") {
      const replayed = internal?.tokenOverride;
      const tokenSource =
        replayed != null ? async (): Promise<string | null> => replayed : options.getToken;
      if (permissive) {
        if (tokenSource) {
          const token = await tokenSource();
          sentBearer = token;
          if (token) headers.Authorization = `Bearer ${token}`;
        }
      } else {
        if (!tokenSource) {
          throw new Error(
            `Route declared [auth] but no token source was configured (getToken) (${method} ${op.path})`,
          );
        }
        const token = await tokenSource();
        sentBearer = token;
        if (!token) {
          throw new Error(
            `The configured token source returned no token for an [auth] route (${method} ${op.path})`,
          );
        }
        headers.Authorization = `Bearer ${token}`;
      }
    } else if (scheme === "cookie" && authMode === "required") {
      // An [auth] route uses the browser's session cookies; reject
      // configurations that would strip them rather than sending the
      // request unauthenticated.
      if (credentials === "omit") {
        throw new Error(
          `Route declared [auth] but options.credentials is "omit"; refusing to send an unauthenticated request (${method} ${op.path})`,
        );
      }
    }

    // Anti-CSRF proof on mutating requests when configured (cookie
    // scheme). GET/HEAD/OPTIONS are safe methods and never carry it.
    if (
      scheme === "cookie" &&
      options.csrfHeader != null &&
      !["GET", "HEAD", "OPTIONS"].includes(method.toUpperCase())
    ) {
      const csrfToken = await options.csrfToken?.();
      if (csrfToken) headers[options.csrfHeader] = csrfToken;
    }

    // Only credentialless calls to routes declaring `[allow_redirects]`
    // follow redirects. Calls carrying auth or cookies do not, because the
    // guard sees only the initial URL and a 3xx could redirect to http://.
    const canFollowRedirects =
      authMode === "none" && credentials === "omit" && op.allowRedirects === true;
    const response = await boundFetch(url, {
      ...options.requestInit,
      ...(authMode !== "none" ? { cache: "no-store" as const } : {}),
      redirect: canFollowRedirects ? "follow" : "error",
      method,
      credentials,
      headers,
      body: args?.body !== undefined ? JSON.stringify(args.body) : undefined,
    });

    if (!response.ok) {
      // Replay hook: bearer scheme only. Cookie credentials cannot be
      // changed by this transport, so a cookie 401 is final. The replay is
      // bounded and uses the hook's return value; re-reading `getToken`
      // could re-send under a different session.
      if (
        response.status === 401 &&
        authMode === "required" &&
        scheme === "bearer" &&
        options.onUnauthorized != null &&
        (internal?.replays ?? 0) < MAX_REPLAYS
      ) {
        let fresh: string | null = null;
        try {
          fresh = await options.onUnauthorized();
        } catch {
          // Renewal failed in the application hook. Surface the server's 401
          // response instead of the hook's error.
          fresh = null;
        }
        if (fresh !== null && fresh !== sentBearer) {
          // Release the rejected response's connection before replaying.
          await releaseBody(response);
          return executeInternal<T>(op, args, {
            replays: (internal?.replays ?? 0) + 1,
            tokenOverride: fresh,
          });
        }
      }
      const text = await response.text();
      let message: string;
      let errorBody: unknown;
      try {
        const json = JSON.parse(text);
        message = json.error ?? json.message ?? text;
        errorBody = json;
      } catch {
        message = text;
      }
      const error = new ApiError(message, response.status, errorBody);
      // Do not let an error observer replace the ApiError.
      notifyObserver(() => options.onError?.(error));
      throw error;
    }

    // Give onResponse its own clone so reading the body there cannot
    // consume the transport's copy below. The clone is only created when an
    // observer is configured; observer errors do not affect the call.
    notifyObserver(() => options.onResponse?.(op, response.clone()));

    if (op.response === "raw") return response as unknown as T;
    if (op.response === "void") {
      // An observer got a clone above, and a clone tees the body: cancelling
      // one branch only settles once the sibling is consumed or cancelled,
      // so awaiting cancel() would hang while the observer's copy is unread.
      // Drain the original in that case; it settles the tee and frees the
      // connection either way. With no observer, cancellation is immediate.
      if (options.onResponse != null) {
        await drainBody(response);
      } else {
        await releaseBody(response);
      }
      return undefined as T;
    }
    const text = await response.text();
    return (text ? JSON.parse(text) : undefined) as T;
  }

  const transport: Transport = {
    execute: <T>(op: Readonly<OperationSpec>, args?: CallArgs) =>
      executeInternal<T>(op, args),
    urlFor: (op, args) => buildUrl(op, args),
    connect: <TSend, TReceive, TBinary extends WsBinaryMode = "none">(
      op: Readonly<OperationSpec>,
      args?: CallArgs,
    ) =>
      connectWs<TSend, TReceive>(op, args) as unknown as Promise<
        TypedWebSocket<TSend, TReceive, TBinary>
      >,
  };

  async function connectWs<TSend, TReceive>(
    op: Readonly<OperationSpec>,
    args?: CallArgs,
  ): Promise<TypedWebSocket<TSend, TReceive>> {
    // Convert http(s) to ws(s).
    const wsBase = baseUrl.replace(/^http/, (m) => (m === "https" ? "wss" : "ws"));

    let url = `${wsBase}${interpolate(op, args)}`;
    if (args?.query) {
      const params = new URLSearchParams();
      appendQuery(params, args.query);
      const qs = params.toString();
      if (qs) url += `?${qs}`;
    }

    // Run the ticket handshake first: the long-lived credential is sent in
    // the header, and only the single-use ticket it returns is added to the
    // URL. The mint is declared by the flow.
    const ticketKey = policy.wsTicket ?? null;
    if (op.ws && op.auth === "required" && scheme === "bearer" && ticketKey != null) {
      // Authenticated ticket roundtrip. The server issues a single-use,
      // short-TTL ticket bound to the caller and consumes it on upgrade.
      const { ticket } = await executeInternal<{ ticket: string }>(ticketKey, undefined);
      url += `${url.includes("?") ? "&" : "?"}ticket=${encodeURIComponent(ticket)}`;
    }

    // Cookie `required` routes use same-origin session cookies. The
    // WebSocket API has no credentials option, so `"omit"` would send the
    // upgrade unauthenticated; reject it as the fetch path does. `optional`
    // routes allow anonymous upgrades.
    if (scheme === "cookie" && op.auth === "required" && credentials === "omit") {
      throw new Error(
        `Route declared [ws][auth] but options.credentials is "omit"; refusing to send an unauthenticated upgrade (${op.method} ${op.path})`,
      );
    }

    assertSecureTransport(url, {
      allowInsecureHttp: options.allowInsecureHttp === true,
      auth: op.auth !== "none",
      credentials,
    });
    return createTypedWebSocket<TSend, TReceive>(new WebSocket(url), op.wsBinary);
  }

  return transport;
}

// ---------------------------------------------------------------------------
// Typed WebSocket
// ---------------------------------------------------------------------------

/** JSON-frame surface shared by every typed WebSocket wrapper. */
export interface TypedWebSocketBase<TSend, TReceive> {
  send(event: TSend): void;
  /** Subscribe to socket events. Registering twice adds two listeners;
   *  each is called. */
  onOpen(handler: () => void): void;
  onMessage(handler: (event: TReceive) => void): void;
  onError(handler: (event: unknown) => void): void;
  onClose(handler: (event: unknown) => void): void;
  /** Close the socket. An application close code and reason are passed to
   *  the underlying WebSocket's close handshake when given. */
  close(code?: number, reason?: string): void;
  readonly readyState: number;
}

/** Added to the wrapper when the route declares client-to-server binary
 *  frames (`binary_send` / `binary`). */
export interface BinarySendMethods {
  /** Send one binary frame verbatim — no JSON envelope is applied. */
  sendBinary(data: BinaryPayload): void;
}

/** Added to the wrapper when the route declares server-to-client binary
 *  frames (`binary_receive` / `binary`). */
export interface BinaryReceiveMethods {
  /** Subscribe to binary frames. Each frame is delivered as the raw
   *  ArrayBuffer (the socket's `binaryType` is forced to `"arraybuffer"`)
   *  and never mixed into `onMessage`'s JSON codec. Registering twice adds
   *  two listeners; each is called. */
  onBinary(handler: (data: ArrayBuffer) => void): void;
}

/** The typed WebSocket wrapper. The JSON event surface is identical for
 *  every route; binary methods appear only when the route's declared
 *  `wsBinary` mode asks for them. */
export type TypedWebSocket<
  TSend,
  TReceive,
  TBinary extends WsBinaryMode = "none",
> = TBinary extends "both"
  ? TypedWebSocketBase<TSend, TReceive> & BinarySendMethods & BinaryReceiveMethods
  : TBinary extends "send"
    ? TypedWebSocketBase<TSend, TReceive> & BinarySendMethods
    : TBinary extends "receive"
      ? TypedWebSocketBase<TSend, TReceive> & BinaryReceiveMethods
      : TypedWebSocketBase<TSend, TReceive>;

export function createTypedWebSocket<TSend, TReceive>(
  ws: WebSocket,
  binary: "send" | "receive" | "both" | "none" = "none",
): TypedWebSocketBase<TSend, TReceive> {
  // Buffer incoming frames as ArrayBuffers on receive routes: Blob (the
  // default) cannot be handed to native zero-copy, and the declared
  // contract is an ArrayBuffer. JSON-only routes never receive binary
  // frames, so their binaryType stays untouched.
  if (binary === "receive" || binary === "both") {
    ws.binaryType = "arraybuffer";
  }

  const handlers = {
    send: (event: TSend) => ws.send(JSON.stringify(event)),
    // Cast to BufferSource: DOM typings disagree across TS versions on
    // whether ArrayBufferView may back a SharedArrayBuffer; every
    // BinaryPayload variant is sendable at runtime.
    sendBinary: (data: BinaryPayload) => ws.send(data as BufferSource),
    // addEventListener (not onX property assignment) so multiple
    // subscribers all fire instead of silently replacing each other.
    onOpen: (handler: () => void) => {
      ws.addEventListener("open", () => handler());
    },
    onMessage: (handler: (event: TReceive) => void) => {
      ws.addEventListener("message", (raw) => {
        const data = (raw as MessageEvent).data;
        // Text frames carry the JSON event codec. Binary frames belong to
        // the route's binary contract (onBinary); a JSON-only route drops
        // them rather than parsing garbage.
        if (typeof data !== "string") return;
        handler(JSON.parse(data) as TReceive);
      });
    },
    onBinary: (handler: (data: ArrayBuffer) => void) => {
      ws.addEventListener("message", (raw) => {
        const data = (raw as MessageEvent).data;
        if (typeof data === "string") return;
        handler(data as ArrayBuffer);
      });
    },
    onError: (handler: (event: unknown) => void) => {
      ws.addEventListener("error", (event) => handler(event));
    },
    onClose: (handler: (event: unknown) => void) => {
      ws.addEventListener("close", (event) => handler(event));
    },
    // Forward args only when given: DOM WebSocket's close overloads and
    // React Native's do not accept an explicit `undefined`.
    close: (code?: number, reason?: string) => {
      if (code === undefined) ws.close();
      else if (reason === undefined) ws.close(code);
      else ws.close(code, reason);
    },
    get readyState() {
      return ws.readyState;
    },
  };
  // Binary methods are always implemented; the route's declared `wsBinary`
  // mode decides — via the `TypedWebSocket` conditional type at `connect` —
  // whether callers may see and call them.
  return handlers as TypedWebSocketBase<TSend, TReceive>;
}